// Scratch independent reimplementation for probing b58encode_check
const crypto = require('node:crypto');

const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

function b58encode(buf) {
  // count leading zero bytes
  let nPad = 0;
  while (nPad < buf.length && buf[nPad] === 0) nPad++;
  // big-endian bytes -> BigInt
  let n = 0n;
  for (const b of buf) n = n * 256n + BigInt(b);
  let out = '';
  while (n > 0n) {
    const r = n % 58n;
    n = n / 58n;
    out = ALPHABET[Number(r)] + out;
  }
  return '1'.repeat(nPad) + out;
}

function b58decode(s) {
  let nPad = 0;
  while (nPad < s.length && s[nPad] === '1') nPad++;
  let n = 0n;
  for (const ch of s) {
    const i = ALPHABET.indexOf(ch);
    if (i < 0) throw new Error('bad char ' + ch);
    n = n * 58n + BigInt(i);
  }
  const bytes = [];
  while (n > 0n) { bytes.unshift(Number(n % 256n)); n = n / 256n; }
  return Buffer.from(new Array(nPad).fill(0).concat(bytes));
}

function sha256(b) { return crypto.createHash('sha256').update(b).digest(); }

function checksum(payload) { return sha256(sha256(payload)).subarray(0, 4); }

function b58encode_check(payload) {
  return b58encode(Buffer.concat([payload, checksum(payload)]));
}

function b58decode_check(s) {
  const full = b58decode(s);
  const payload = full.subarray(0, full.length - 4);
  const ck = full.subarray(full.length - 4);
  const exp = checksum(payload);
  if (!ck.equals(exp)) throw new Error('Invalid checksum');
  return payload;
}

// Python bytes repr emulation
function pyRepr(buf) {
  let hasSingle = false, hasDouble = false;
  for (const b of buf) { if (b === 0x27) hasSingle = true; if (b === 0x22) hasDouble = true; }
  const q = (hasSingle && !hasDouble) ? '"' : "'";
  let s = "b" + q;
  for (const b of buf) {
    if (b === 0x5c) s += '\\\\';
    else if (b === 0x0a) s += '\\n';
    else if (b === 0x0d) s += '\\r';
    else if (b === 0x09) s += '\\t';
    else if (String.fromCharCode(b) === q) s += '\\' + q;
    else if (b >= 0x20 && b < 0x7f) s += String.fromCharCode(b);
    else s += '\\x' + b.toString(16).padStart(2, '0');
  }
  return s + q;
}

module.exports = { ALPHABET, b58encode, b58decode, sha256, checksum, b58encode_check, b58decode_check, pyRepr };

if (require.main === module) {
  const mode = process.argv[2];
  if (mode === 'enc_check_utf8') {
    const payload = Buffer.from(process.argv[3], 'utf8');
    console.log(pyRepr(Buffer.from(b58encode_check(payload), 'ascii')));
  } else if (mode === 'enc_check_hex') {
    const payload = Buffer.from(process.argv[3], 'hex');
    console.log(pyRepr(Buffer.from(b58encode_check(payload), 'ascii')));
  } else if (mode === 'enc_check_b58payload') {
    // payload = b58decode(argv[3]) -- mirrors line 10 (enc_check2 = encode_check(dec1))
    const payload = b58decode(process.argv[3]);
    console.log('payloadHex=' + payload.toString('hex'));
    console.log(pyRepr(Buffer.from(b58encode_check(payload), 'ascii')));
  } else if (mode === 'sha') {
    const payload = Buffer.from(process.argv[3], 'utf8');
    console.log('sha1x=' + sha256(payload).toString('hex'));
    console.log('sha2x=' + sha256(sha256(payload)).toString('hex'));
    console.log('ck=' + checksum(payload).toString('hex'));
  }
}

