// generate random valid-UTF8 payload strings, base64-encoded one per line
const fs=require("fs");
let seed=987654321n;
function rnd(){ seed=(seed*6364136223846793005n+1442695040888963407n)&((1n<<64n)-1n); return Number(seed>>33n)/ (2**31); }
const lines=[];
for(let i=0;i<60;i++){
  const len=Math.floor(rnd()*80);
  let s="";
  for(let j=0;j<len;j++){
    const r=rnd();
    let cp;
    if(r<0.4) cp=0x20+Math.floor(rnd()*0x5f);          // ascii printable
    else if(r<0.55) cp=1+Math.floor(rnd()*0x1f);        // C0 controls (no NUL)
    else if(r<0.75) cp=0x80+Math.floor(rnd()*0x700);    // 2-byte utf8
    else if(r<0.92) cp=0x1000+Math.floor(rnd()*0xd000-1); // 3-byte (avoid surrogates below)
    else cp=0x10000+Math.floor(rnd()*0xf0000);          // 4-byte
    if(cp>=0xd800&&cp<=0xdfff) cp=0x2603;
    if(cp>0x10ffff) cp=0x1f600;
    s+=String.fromCodePoint(cp);
  }
  lines.push(Buffer.from(s,"utf8").toString("base64"));
}
fs.writeFileSync("/tmp/fuzz.txt", lines.join("\n")+"\n");
